#include <stdio.h>
int main(void) {
    int n = 3;
    int values[3] = {-2, 0, 3};
    int ordered = 1;
    for (int i = 0; i < n - 1; i = i + 1) {
        if (values[i] > values[i + 1]) {
            ordered = 0;
            break;
        }
    }
    printf("%d\n", ordered);
    return 0;
}
